package com.renthub.payment; import com.renthub.auth.AuthService; import com.renthub.booking.*; import com.renthub.user.User; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*; @RestController @RequestMapping("/api/payments") @CrossOrigin(origins="http://localhost:5173") public class PaymentController{private final PaymentRepository repo;private final BookingRepository bookings;private final AuthService auth;public PaymentController(PaymentRepository r,BookingRepository b,AuthService a){repo=r;bookings=b;auth=a;} @PostMapping("/booking/{id}") public Payment pay(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id,@RequestBody(required=false)Map<String,Object>body){User u=auth.require(h);Booking b=bookings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));if(!b.getUserId().equals(u.getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Not your booking");if("CANCELLED".equals(b.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Cancelled booking cannot be paid");Payment p=repo.findByBookingId(id).orElseGet(Payment::new);p.setBookingId(id);p.setUserId(u.getId());p.setAmount(b.getTotalAmount());p.setMethod(body==null?"CARD":String.valueOf(body.getOrDefault("method","CARD")));p.setStatus("PAID");p.setReferenceNo("RH-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());p=repo.save(p);b.setStatus("PAID");bookings.save(b);return p;}}
